"""Snap span edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def _check_step(step: int) -> None:
    if step <= 0:
        raise ValueError(f"step must be positive: {step}")
    if 60 % step:
        raise ValueError(f"step must divide 60: {step}")

def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step. Halves round up."""
    return (minute + step // 2) // step * step

def _duration(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{hours}h {minutes:02d}m"

# ---
def round_spans(
    spans: Iterable[Span], step: int
) -> List[Span]:
    """Round each start and end to the nearest step.

    A step of zero, a negative step or one that does not
    divide an hour raises ValueError. So does a span that
    shrinks to nothing once rounded.
    """
    _check_step(step)
    return [
        Span(_snap(s.start, step), _snap(s.end, step))
        for s in spans
    ]

# ---
def label_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels like 09:00-17:15 (8h 15m), rounded."""
    return [
        f"{format_span(s)} ({_duration(s)})"
        for s in round_spans(spans, step)
    ]

