# owner: platform
import unittest

from hourglass.rounding import label_spans, round_spans
from hourglass.models import Span

class RoundTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        # 09:07-17:08 with a fifteen minute step
        got = round_spans([Span(547, 1028)], 15)
        self.assertEqual(got, [Span(540, 1035)])

    def test_halves_round_up(self):
        got = round_spans([Span(15, 75)], 30)
        self.assertEqual(got, [Span(30, 90)])

    def test_exact_values_unchanged(self):
        got = round_spans([Span(60, 120)], 30)
        self.assertEqual(got, [Span(60, 120)])

    def test_empty(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(60, 120)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(60, 65)], 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        got = label_spans([Span(541, 1034)], 15)
        self.assertEqual(got, ["09:00-17:15 (8h 15m)"])

    def test_label_per_span(self):
        got = label_spans([Span(0, 60), Span(90, 120)], 30)
        self.assertEqual(got, [
            "00:00-01:00 (1h 00m)",
            "01:30-02:00 (0h 30m)"
        ])

    def test_label_rejects_bad_step(self):
        with self.assertRaises(ValueError):
            label_spans([Span(60, 120)], 0)
